function chapterChanged(){state.chapter=Number($('chapter').value);state.records=state.manifest.text_records.filter(r=>r.chapter===state.chapter&&($('include-silent').checked||buildTimeline(r.text_verbatim,sceneVoices.lines).turns.some(t=>t.audio)));$('beat').replaceChildren();state.records.forEach((r,i)=>option($('beat'),i,(state.manifest.scenes.find(s=>s.id===r.scene)?.room_key||'Story')+' · '+r.field+' · '+r.text_verbatim.replaceAll('\n',' ').slice(0,65)));state.beat=Math.max(0,state.records.findIndex(r=>state.chapter===1&&r.field==='entry_text'&&state.manifest.scenes.find(s=>s.id===r.scene)?.room_key==='workshop'));loadBeat();}
